> +		clk_base = h->t_lra_us;
> +		divider = 4;
> +		break;
> +	case PLAY_RATE_T_LRA_DIV_8:
> +		clk_base = h->t_lra_us;
> +		divider = 8;
> +		break;
> +	case PLAY_RATE_T_LRA_X_2:
> +		clk_base = h->t_lra_us;
> +		multiplier = 2;
> +		break;
> +	case PLAY_RATE_T_LRA_X_4:
> +		clk_base = h->t_lra_us;
> +		multiplier = 4;
> +		break;
> +	case PLAY_RATE_T_LRA_X_8:
> +		clk_base = h->t_lra_us;
> +		multiplier = 8;
> +		break;
> +	case PLAY_RATE_F_8KHZ:
> +		divider = 8;
> +		break;
> +	case PLAY_RATE_F_16KHZ:
> +		divider = 16;
> +		break;
> +	case PLAY_RATE_F_24KHZ:
> +		divider = 24;
> +		break;
> +	case PLAY_RATE_F_32KHZ:
> +		divider = 32;
