- 	for (j = 0;  j < stream_count; j++) {
- 		if (stream_set[j] && stream_set[j]->triggered_crtc_reset.enabled) {
- 			int refresh_rate = 0;
- 
- 			refresh_rate = (stream_set[j]->timing.pix_clk_100hz*100)/
- 				(stream_set[j]->timing.h_total*stream_set[j]->timing.v_total);
