- static int
- amdgpu_dm_connector_atomic_check(struct drm_connector *conn,
- 				 struct drm_atomic_commit *state)
- {
- 	struct drm_connector_state *new_con_state =
- 		drm_atomic_get_new_connector_state(state, conn);
